let sensor1 = flow.get('sensor1');
let sensor2 = flow.get('sensor2');

// Recebe Sensor1
if (msg.topic === 'senai/temperatura/sensor1') {
    sensor1 = Number(msg.payload);
    flow.set('sensor1', sensor1);
}

// Recebe Sensor2
if (msg.topic === 'senai/temperatura/sensor2') {
    sensor2 = Number(msg.payload);
    flow.set('sensor2', sensor2);
}

// Espera os dois sensores
if (sensor1 === undefined || sensor2 === undefined) {
    return null;
}

// Proteção contra valores fora da faixa
if (sensor1 > 30 || sensor1 < 15) {
    node.warn(
        `Leitura ignorada: Sensor1 fora da faixa permitida (${sensor1}°C)`
    );
    return null;
}

// ======================================
// MONITORAMENTO DE VARIAÇÃO EM 1 MINUTO
// ======================================

let historico = flow.get('historicoSensor1') || [];

historico.push({
    temperatura: sensor1,
    timestamp: Date.now()
});

// Mantém apenas os últimos 60 segundos
historico = historico.filter(item =>
    (Date.now() - item.timestamp) <= 60000
);

flow.set('historicoSensor1', historico);

// Compara com a leitura mais antiga do último minuto
if (historico.length > 1) {

    let temperatura1MinAtras = historico[0].temperatura;

    let variacao = Math.abs(sensor1 - temperatura1MinAtras);

    if (variacao >= 5) {

        node.warn(
            `ALERTA! Sensor1 variou ${variacao.toFixed(2)}°C em menos de 1 minuto. ` +
            `Anterior=${temperatura1MinAtras}°C Atual=${sensor1}°C`
        );
    }
}

// ======================================
// COMPARAÇÃO ENTRE SENSORES
// ======================================

let differential = Math.abs(sensor1 - sensor2);

let status = 'NORMAL';

if (differential > 5 && differential < 15) {
    status = 'ALERT';
}

if (differential >= 15) {
    status = 'DANGER';
}

// ======================================
// INSERT MYSQL
// ======================================

msg.topic = `
INSERT INTO temperaturas2
(sensor1, sensor2, diferencial, status)
VALUES (?, ?, ?, ?)
`;
node.warn(
        `Dado armazenado com sucesso, Sensor1: (${sensor1}°C)`
    );
msg.payload = [
    sensor1,
    sensor2,
    differential,
    status
];

return msg;
